/*
 * The template's items become UNSHARED steps after the plan's last one, so the learner
 * sees nothing until the coach shares them. Positions stay 1..n.
 *  - live: 'to book', the template's duration (60 if none). No date: the session is booked.
 *  - homework: copied from its library item (SCOPE R4: a later library edit never reaches
 *    it), due at 18:00 Paris on today + the item's day offset.
 *  - check-in: a copy of the item's form (by id), else "After a session" (DBU-10), sent at
 *    09:00 Paris on today + offset.
 * Runs when the forms arrive, which the job asked for (sft_ask).
 */
const job = Inputs.job;
if (job && typeof job === 'object') {
  (async () => {
    try {
      const R = Noodl.Records;
      const q = (c, where) => R.query(c, where, { limit: 1000, plain: true });
      const planId = String(job.planId || '');
      const learnerId = String(job.learnerId || '');
      const templateId = String(job.templateId || '');
      if (!planId || !learnerId) throw new Error('no plan or learner in the job');
      const found = templateId ? await q('PlanTemplate', { objectId: { equalTo: templateId } }) : [];
      if (found.length !== 1) {
        Outputs.reason = 'That plan template no longer exists. Choose another, or start with an empty plan.';
        Outputs.missing();
        return;
      }
      const items = Array.isArray(found[0].items) ? found[0].items : [];
      const forms = Array.isArray(Inputs.forms) ? Inputs.forms : [];
      const formOf = (id) => forms.find((f) => f.id === id) || forms.find((f) => f.id === 'after-session');
      if (!formOf('after-session')) throw new Error('no after-session form');

      const TZ = 'Europe/Paris';
      const offsetMs = (utc) => {
        const fmt = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
        const p = Object.fromEntries(fmt.formatToParts(new Date(utc)).map((x) => [x.type, x.value]));
        return Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second) - utc;
      };
      const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });
      const parisAt = (days, hh) => {
        const [y, m, d] = today.split('-').map(Number);
        const guess = Date.UTC(y, m - 1, d + days, hh, 0);
        return new Date(guess - offsetMs(guess)).toISOString();
      };
      const offset = (i) => (Number.isInteger(i.dayOffset) && i.dayOffset >= 0 ? i.dayOffset : 0);

      const existing = await q('Step', { plan: { equalTo: planId } });
      const last = existing.reduce((m, s) => Math.max(m, Number(s.position) || 0), 0);
      const libraryIds = items.map((i) => i.libraryItem).filter(Boolean);
      const library = libraryIds.length ? await q('LibraryItem', { objectId: { containedIn: libraryIds } }) : [];
      const firstStatus = { live: 'to_book', homework: 'not_started', checkin: 'scheduled' };

      let added = 0;
      for (const item of items) {
        if (!firstStatus[item.kind]) continue;
        const step = { plan: planId, learner: learnerId, position: last + added + 1, kind: item.kind, title: String(item.title || ''), shared: false, status: firstStatus[item.kind] };
        if (item.kind === 'live') step.durationMin = Number.isInteger(item.durationMin) ? item.durationMin : 60;
        if (item.kind === 'homework') {
          step.dueAt = parisAt(offset(item), 18);
          step.handInChecklist = [];
          step.resources = [];
          const lib = library.find((l) => l.objectId === item.libraryItem);
          if (lib) Object.assign(step, { fromLibraryItem: lib.objectId, brief: lib.brief || '', handInChecklist: lib.handInChecklist || [], resources: lib.resources || [] });
        }
        if (item.kind === 'checkin') {
          step.sendsAt = parisAt(offset(item), 9);
          step.form = formOf(item.form);
        }
        await R.create('Step', step);
        added++;
      }
      Outputs.added = added;
      Outputs.done();
    } catch (e) {
      console.error('[dbu:Steps from template]', String((e && e.message) || e));
      Outputs.reason = 'The template could not be applied. Try again.';
      Outputs.failed();
    }
  })();
}
